/* From Uiverse.io by Nayzerftn - Tags: button, hover, active */
.__UIV_SCOPE__ .btn-hover {
  position: relative;
  display: inline-block;
  padding: 15px 30px;
  font-size: 18px;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: #ffffff;
  background-color: #4b4b4b;
  border: none;
  outline: none;
  overflow: hidden;
  cursor: pointer;
  transition: all 0.3s ease-out;
}

.__UIV_SCOPE__ .btn-hover:hover {
  background-color: #522ba7;
}

.__UIV_SCOPE__ .btn-hover::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(0);
  width: 15px;
  height: 15px;
  border-radius: 50%;
  background-color: #ffffff;
  opacity: 0.8;
  transition: all 0.5s ease-out;
}

.__UIV_SCOPE__ .btn-hover:hover::before {
  transform: translate(-50%, -50%) scale(20);
  opacity: 0;
}
